contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, string calldata description) public {
        require(caller != address(0), "caller must not be zero");

        address team = c.jojoTeam();

        bool reverted;
        if (caller == team) {
            c.newEmergencyOracle(description);
            reverted = false;
        } else {
            try c.newEmergencyOracle(description) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        assert(caller != team || !reverted);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, string calldata description) public {
        require(caller != address(0), "caller must not be zero");

        address team = c.jojoTeam();

        bool callerIsTeam = caller == team;
        bool reverted;

        if (callerIsTeam) {
            try c.newEmergencyOracle(description) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.newEmergencyOracle(description) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        assert(callerIsTeam != reverted);
    }

    receive() external payable {}
}
